(async () => {
  const repository = 'Arianagu2332/Kvasir_ST_tool';
  const manifestUrl = `https://raw.githubusercontent.com/${repository}/refs/heads/main/script-manifest.json`;
  let revision = '1ae2e6f7ff62b1daa91229f092741b5fab62f0e1';
  try {
    const response = await fetch(`${manifestUrl}?kvasir=${Date.now()}`, { cache: 'no-store' });
    if (!response.ok) throw new Error(`HTTP ${response.status}`);
    const manifest = await response.json();
    if (typeof manifest?.revision !== 'string' || !/^[0-9a-f]{40}$/.test(manifest.revision)) throw new Error('无效的脚本版本清单');
    revision = manifest.revision;
  } catch (error) {
    console.warn('[Kvasir] 无法读取脚本版本清单，使用内置的已知版本', error);
  }
  await import(`https://cdn.jsdelivr.net/gh/${repository}@${revision}/dist/Kvasir/index.js`);
})().catch(error => console.error('[Kvasir] 脚本加载失败', error));
